import pathlib
import sys
import unittest


sys.path.insert(0, str(pathlib.Path(__file__).parent))
import reparse  # noqa: E402


class TestTargetPlayerDraw(unittest.TestCase):
    def map_draw(self, text):
        verb, args = reparse.O.parse_atom(text)
        return reparse.map_atom(verb, args, kind="oneshot")

    def test_target_player(self):
        result = self.map_draw("Target player draws two cards.")
        self.assertEqual(result, ('draw', {'amount': 2}, {'filter': 'player'}))

    def test_target_opponent(self):
        result = self.map_draw("Target opponent draws two cards.")
        self.assertEqual(result, ('draw', {'amount': 2, 'target': 'opponent'}, None))

    def test_each_opponent(self):
        result = self.map_draw("Each opponent draws two cards.")
        self.assertEqual(result, ('draw', {'amount': 2, 'target': 'opponent'}, None))

    def test_each_player(self):
        result = self.map_draw("Each player draws two cards.")
        self.assertIsNone(result)

    def test_that_player(self):
        result = self.map_draw("That player draws two cards.")
        self.assertIsNone(result)


if __name__ == "__main__":
    unittest.main()
